import pandas as pd

def clean(df):
    df = df.copy()
    if "Order_ID" in df.columns:
        df = df.drop_duplicates(subset=["Order_ID"], keep="first")
    if "Category" in df.columns:
        allowed = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
        mapping = {value.lower(): value for value in allowed}
        df["Category"] = df["Category"].astype(str).str.strip().map(
            lambda x: mapping.get(x.lower(), x)
        )
    return df

def answer(df):
    counts = df.groupby("Category", dropna=False).size()
    result = {}
    for key, value in counts.items():
        if pd.isna(key):
            continue
        result[str(key)] = int(value)
    return result
